@router.get("/api/v1/wallets/{wallet_id}/transactions/cursor")
async def stream_wallet_transactions(
    wallet_id: str,
    cursor_timestamp: Optional[datetime] = Query(None),
    cursor_id: Optional[int] = Query(None),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    wallet_stmt = select(Wallet).where(Wallet.id == wallet_id, Wallet.user_id == current_user.id)
    res = await db.execute(wallet_stmt)
    if not res.scalar_one_or_none():
        raise HTTPException(status_code=404, detail="Wallet not found or access denied")

    async def transaction_generator():
        stmt = select(WalletTransaction).where(WalletTransaction.wallet_id == wallet_id)
